import{_ as a,o as e,c as n,a2 as l}from"./chunks/framework.BG8d4IEm.js";const b=JSON.parse('{"title":"什么是 TypeScript 中的类型,两种观点","description":"","frontmatter":{"tags":["TypeScript","翻译"]},"headers":[],"relativePath":"posts/2020-02-29-understanding-types-typescript.md","filePath":"posts/2020-02-29-understanding-types-typescript.md"}'),p={name:"posts/2020-02-29-understanding-types-typescript.md"};function o(r,s,t,c,i,y){return e(),n("div",null,[...s[0]||(s[0]=[l(`<h1 id="什么是-typescript-中的类型-两种观点" tabindex="-1">什么是 TypeScript 中的类型,两种观点 <a class="header-anchor" href="#什么是-typescript-中的类型-两种观点" aria-label="Permalink to &quot;什么是 TypeScript 中的类型,两种观点&quot;">​</a></h1><blockquote><p>该译文对应原文 <a href="https://2ality.com/2020/02/understanding-types-typescript.html" target="_blank" rel="noreferrer">What is a type in TypeScript? Two perspectives</a></p></blockquote><h2 id="_1-三个问题针对每种观点" tabindex="-1">1 三个问题针对每种观点 <a class="header-anchor" href="#_1-三个问题针对每种观点" aria-label="Permalink to &quot;1 三个问题针对每种观点&quot;">​</a></h2><p>以下三个问题对理解类型系统如何工作至关重要。每个问题都需要采用两种观点来解答。</p><ol><li><p><code>myVariable</code> 属于类型 <code>MyType</code> 意味着什么</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#F97583;">let</span><span style="color:#E1E4E8;"> myVariable</span><span style="color:#F97583;">:</span><span style="color:#B392F0;"> MyType</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p><code>SourceType</code> 赋给了 <code>TargetType</code> 么</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#F97583;">let</span><span style="color:#E1E4E8;"> source</span><span style="color:#F97583;">:</span><span style="color:#B392F0;">SourceType</span><span style="color:#F97583;"> =</span><span style="color:#6A737D;"> /*...*/</span></span>
<span class="line"><span style="color:#F97583;">let</span><span style="color:#E1E4E8;"> target</span><span style="color:#F97583;">:</span><span style="color:#B392F0;">TargetType</span><span style="color:#F97583;"> =</span><span style="color:#E1E4E8;"> source</span><span style="color:#6A737D;">/*...*/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>TypeUnion 如何从 Type1，Type2和 Type3 中派生的？</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#F97583;">type</span><span style="color:#B392F0;"> typeUnion</span><span style="color:#F97583;"> =</span><span style="color:#B392F0;"> Type1</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> Type2</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> Type3</span><span style="color:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ol><h2 id="_2-观点一-类型是值的集合" tabindex="-1">2 观点一：类型是值的集合 <a class="header-anchor" href="#_2-观点一-类型是值的集合" aria-label="Permalink to &quot;2 观点一：类型是值的集合&quot;">​</a></h2><p>在这种视角下,类型是值的的集合</p><ol><li>如果 <code>myVariable</code> 属于类型 <code>MyType</code>,表示所有可以赋给 <code>myVariable</code> 的值都必须是属于 <code>MyType</code> 集合的元素</li><li><code>sourceType</code> 可以赋给 <code>TargetType</code> 是 <code>SourceType</code> 为 <code>TargetType</code> 的子集。</li><li>联合类型(TypeUnion) 属于类型 <code>Type1</code>,<code>Type2</code> 和 <code>Type3</code> 是集合理论的并集</li></ol><h2 id="_3-观点-2-类型兼容关系" tabindex="-1">3 观点 2: 类型兼容关系 <a class="header-anchor" href="#_3-观点-2-类型兼容关系" aria-label="Permalink to &quot;3 观点 2: 类型兼容关系&quot;">​</a></h2><p>在这种视角下: 我们不关心值和在代码运行时如何变化。取而代之，我们更多采用静态视角。</p><ul><li>源代码都有位置,每个位置都有一个静态类型。在有 TypeScript 识别的编辑器,我们可以看到静态类型的位置如果光标悬停在代码上。</li><li>源码位置通过赋值，函数调用等关联上目标位置时。源码位置对应的类型必须和目标位置的类型兼容。TypeScript 规范定义类型兼容称之为<a href="https://github.com/microsoft/TypeScript/blob/master/doc/spec.md#3.11" target="_blank" rel="noreferrer">类型关联</a></li><li><a href="https://github.com/microsoft/TypeScript/blob/master/doc/spec.md#3114-assignment-compatibility" target="_blank" rel="noreferrer">类型关联赋值兼容性</a> 定义了何时源类型 S 可以赋值给目标类型 T <ul><li>S 和 T 是相同的类型</li><li>S 和 T 是类型 any</li><li>等等</li></ul></li></ul><p>让我们思考上述问题:</p><ol><li><code>myVariable</code> 属于类型 <code>MyType</code> 如果属于 <code>myVariable</code> 的静态类型可以赋给 <code>MyType</code></li><li><code>SourceType</code> 是可以赋给 <code>TargetType</code> 如果它们赋值兼容</li><li>联合类型(type unions) 如何工作参考<a href="https://github.com/microsoft/TypeScript/blob/master/doc/spec.md#3111-apparent-members" target="_blank" rel="noreferrer">类型关系的显示成员</a></li></ol><p>TypeScript 类型系统一个非常有意思的特性是相同的变量可以在不同位置有不同的静态类型。</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#F97583;">const</span><span style="color:#79B8FF;"> arr</span><span style="color:#F97583;"> =</span><span style="color:#E1E4E8;"> [];</span></span>
<span class="line"><span style="color:#6A737D;">// 推导类型: any[]</span></span>
<span class="line"><span style="color:#E1E4E8;">arr;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E1E4E8;">arr.</span><span style="color:#B392F0;">push</span><span style="color:#E1E4E8;">(</span><span style="color:#79B8FF;">123</span><span style="color:#E1E4E8;">);</span></span>
<span class="line"><span style="color:#6A737D;">// 推导类型: number[]</span></span>
<span class="line"><span style="color:#E1E4E8;">arr;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E1E4E8;">arr.</span><span style="color:#B392F0;">push</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&#39;abc&#39;</span><span style="color:#E1E4E8;">);</span></span>
<span class="line"><span style="color:#6A737D;">// 推导类型: (string | number)[]</span></span>
<span class="line"><span style="color:#E1E4E8;">arr;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="_4-标明类型系统-nominal-type-systems-vs-结构类型系统-structural-type-systems" tabindex="-1">4 标明类型系统(Nominal type systems) vs 结构类型系统(structural type systems ) <a class="header-anchor" href="#_4-标明类型系统-nominal-type-systems-vs-结构类型系统-structural-type-systems" aria-label="Permalink to &quot;4 标明类型系统(Nominal type systems) vs 结构类型系统(structural type systems )&quot;">​</a></h2><p>静态类型系统的一个任务是判断两种静态类型是否兼容。</p><ul><li>静态类型 <code>U</code> 是一个实际的参数(例如通过函数调用)</li><li>静态类型 <code>T</code> 是一个相关的格式化参数(指定为函数定义的一部分)</li></ul><blockquote><p>笔者注: 这里 <code>U</code> 是实参(真实传入的值), <code>T</code> 是形参(函数申明传入的变量)</p></blockquote><p>这通常意味着检查 <code>U</code> 是否属于 <code>T</code> 的子类型。两种方法实现这种检查(粗略来看)</p><ul><li>在标明类型系统, 两种静态类型是相等的如果他们拥有相同的标识符(名字),一个类型是另一个的子类型如果它们的子类型关系式显示申明的。 <ul><li>表明类型语言例如 C++,Java,C,Swift 和 Rust</li></ul></li><li>在结构化类型系统, 两种静态类型是相同的如果他们拥有相同的结构(如果它们的各部分名字和类型均相同)。类型 <code>U</code> 是另一种类型 <code>T</code> 的子类型如果 <code>U</code> 拥有类型 <code>T</code> 的所有部分(类型 U 可能还包含其他部分),而且类型 <code>U</code> 的每个部分属于类型 T 相关联部分的子类型. <ul><li>结构化类型语言 OCaml/ReasonML,Haskell 和 TypeScript</li></ul></li></ul><p>以下的代码在标明类型系统中会出错,但在 TypeScript 结构类型系统中是合法的。因为类 A 和 类 B 拥有相同的结构。</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#F97583;">class</span><span style="color:#B392F0;"> A</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#FFAB70;">    name</span><span style="color:#F97583;">:</span><span style="color:#9ECBFF;"> &#39;A&#39;</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"><span style="color:#F97583;">class</span><span style="color:#B392F0;"> B</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#FFAB70;">    name</span><span style="color:#F97583;"> =</span><span style="color:#9ECBFF;"> &#39;B&#39;</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">const</span><span style="color:#79B8FF;"> somaVariable</span><span style="color:#F97583;">:</span><span style="color:#B392F0;">A</span><span style="color:#F97583;"> =</span><span style="color:#F97583;"> new</span><span style="color:#B392F0;"> B</span><span style="color:#E1E4E8;">();</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>TypeScript 接口同样是结构化的。不必为了匹配而实现该接口。</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#F97583;">interface</span><span style="color:#B392F0;"> Point</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#FFAB70;">    x</span><span style="color:#F97583;">:</span><span style="color:#79B8FF;"> number</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">    y</span><span style="color:#F97583;">:</span><span style="color:#79B8FF;"> number</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"><span style="color:#F97583;">const</span><span style="color:#79B8FF;"> point</span><span style="color:#F97583;">:</span><span style="color:#B392F0;"> Point</span><span style="color:#F97583;"> =</span><span style="color:#E1E4E8;"> {x:</span><span style="color:#79B8FF;">1</span><span style="color:#E1E4E8;">, y:</span><span style="color:#79B8FF;">2</span><span style="color:#E1E4E8;">};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="进一步阅读" tabindex="-1">进一步阅读 <a class="header-anchor" href="#进一步阅读" aria-label="Permalink to &quot;进一步阅读&quot;">​</a></h2><ul><li><a href="https://www.typescriptlang.org/docs/handbook/type-compatibility.html" target="_blank" rel="noreferrer">TypeScript 手册类型兼容</a></li><li><a href="https://github.com/microsoft/TypeScript/blob/master/doc/spec.md#3.11" target="_blank" rel="noreferrer">TypeScript 规范类型关系章节</a></li></ul><hr><h2 id="笔者注" tabindex="-1">笔者注 <a class="header-anchor" href="#笔者注" aria-label="Permalink to &quot;笔者注&quot;">​</a></h2><p>理解 TypeScript 是结构化类型系统。可以帮助你更好的使用 TypeScript。</p><p>TypeScript 在设计之初定义了一系列准则，参考<a href="https://github.com/microsoft/TypeScript/wiki/TypeScript-Design-Goals" target="_blank" rel="noreferrer">TypeScript 设计目的</a> 翻译如下:</p><p><strong>目标:</strong></p><ol><li>静态识别可能出错的结构</li><li>提供一个结构机制用于组织大型代码</li><li>产出代码不要增加运行时负担</li><li>产出干净,惯用的,可识别的 js 代码</li><li>产出一种可组合且易于推理的语言</li><li>向当前和未来的 ECMAScript 规范靠拢</li><li>保留所有 JavaScript 代码运行时特性</li><li>避免添加表达式层面的语法</li><li>使用一致,完全可擦除的结构化类型系统</li><li>成为跨平台的工具</li><li>不要和 TypeScript 发生破坏性迭代</li></ol><p><strong>非目标:</strong></p><ol><li>完全模仿现有语言,使用当前 JavaScript 的特性和编程设计者的意图来开发一门更有价值的语言作为替代。</li><li>激进的优化程序运行时性能,产出在运行平台性能更良好的 JavaScript 代码</li><li>专注于完全或证明正确的类型系统,取代在正确性和高产性上进行平衡。</li><li>提供一个端到端的编译管道,取代创建一个可扩展的外部工具用于编译器或其他更复杂的构建流</li><li>在编码中添加或依赖与运行时的类型信息,或产出基于类型系统的不同代码。取代鼓励不依赖于运行时元数据的编程模式</li><li>提供额外的运行时函数或库。取代使用 TypeScript 描述已经存在的库</li><li>引入一些可能使用户惊讶的特性。取代其他语言经过考量而采用的通用模式。</li></ol><p>根据该设计主旨可以看到 TypeScript 的如下特性</p><ol><li>属于静态类型检查 <blockquote><p>这意味着不应该在运行时依赖 TypeScript 类型组织代码逻辑</p></blockquote></li><li>属于结构化类型 <blockquote><p>不要执着于类型的完全匹配只要结构相似就是相同类型</p></blockquote></li><li>类型检查为首要准则 <blockquote><p>TypeScript 准确的说并不是一门语言,它只是类型检查的工具,应该把<strong>学习重点放在更好的类型检查上,而非它所提供的语言特性</strong></p></blockquote></li></ol><p>工作是马拉松而非短跑 保持谦逊,而非愚蠢 和自己比较而非他人 尊重人,而非头衔 选择挑战,而非安逸 工作从白板开始,而非键盘 价值驱动,而非代码 热爱生活,而非工作</p>`,38)])])}const u=a(p,[["render",o]]);export{b as __pageData,u as default};
